  function taData() { return window.ThaiAddressData || { provinces: [], districts: [], subdistricts: [] }; }
  function taFindProvinceId(name) { const hit = taData().provinces.find((p) => p[1] === name); return hit ? hit[0] : null; }
  function taFindDistrictId(name, provinceId) { const hit = taData().districts.find((d) => d[2] === name && (!provinceId || d[1] === provinceId)); return hit ? hit[0] : null; }
  function taProvinceOptions(selected) {
    const opts = ['<option value="">-- เลือกจังหวัด --</option>'];
    taData().provinces.forEach(([, name]) => opts.push(`<option value="${esc(name)}" ${name === selected ? 'selected' : ''}>${esc(name)}</option>`));
    return opts.join('');
  }
  function taDistrictOptions(provinceName, selected) {
    const provinceId = taFindProvinceId(provinceName);
    if (!provinceId) return '<option value="">-- เลือกจังหวัดก่อน --</option>';
    const opts = ['<option value="">-- เลือกอำเภอ/เขต --</option>'];
    taData().districts.filter((d) => d[1] === provinceId).forEach(([, , name]) => opts.push(`<option value="${esc(name)}" ${name === selected ? 'selected' : ''}>${esc(name)}</option>`));
    return opts.join('');
  }
  function taSubdistrictOptions(provinceName, districtName, selected) {
    const provinceId = taFindProvinceId(provinceName); const districtId = taFindDistrictId(districtName, provinceId);
    if (!districtId) return '<option value="">-- เลือกอำเภอ/เขตก่อน --</option>';
    const opts = ['<option value="">-- เลือกตำบล/แขวง --</option>'];
    taData().subdistricts.filter((s) => s[1] === districtId).forEach(([, , name]) => opts.push(`<option value="${esc(name)}" ${name === selected ? 'selected' : ''}>${esc(name)}</option>`));
    return opts.join('');
  }
  function renderAddressGroup(prefix, f, labels) {
    const provinceVal = f[`${prefix}Province`] || ''; const districtVal = f[`${prefix}District`] || ''; const subdistrictVal = f[`${prefix}Subdistrict`] || '';
    return `<div class="form-grid cols-3" style="margin-top:12px" data-address-scope="${prefix}">
      <div class="field"><label for="${prefix}-province">${labels.province}</label><select id="${prefix}-province" name="${prefix}Province" data-address-role="province">${taProvinceOptions(provinceVal)}</select></div>
      <div class="field"><label for="${prefix}-district">${labels.district}</label><select id="${prefix}-district" name="${prefix}District" data-address-role="district" ${!provinceVal ? 'disabled' : ''}>${taDistrictOptions(provinceVal, districtVal)}</select></div>
      <div class="field"><label for="${prefix}-subdistrict">${labels.subdistrict}</label><select id="${prefix}-subdistrict" name="${prefix}Subdistrict" data-address-role="subdistrict" ${!districtVal ? 'disabled' : ''}>${taSubdistrictOptions(provinceVal, districtVal, subdistrictVal)}</select></div>
    </div>`;
  }

