    saveCreateForm(); const state = window.Activity9Store.getState(); const draft = state.createDraft; const source = state.sourceCases.find((item) => item.id === draft.sourceCaseId);
    if (draft.sourceMode === 'Activity5' && state.records.some((r) => r.source.caseId === draft.sourceCaseId && r.dimensions.request !== 'CourtRejected')) throw new Error('สำนวนและบุคคลนี้มีคำขอที่ยังใช้งานอยู่ กรุณาเปิดแฟ้มเดิม');
    const created = window.Activity9Store.mutate('create:submit', (next) => {
      const n = next.records.length + 1; const id = `AW-DEMO-${String(n).padStart(4, '0')}`; const subject = source?.subjects[0] || { personId: `P-MANUAL-${n}`, name: draft.subjectName || 'นาย ก.', citizenId: draft.citizenId || '1-10XX-XXXXX-21-4' };
      const record = { id, systemRef: `AW-2569-${String(n).padStart(6, '0')}`, requestNo: `คขม-${String(n).padStart(4, '0')}/2569`, warrantNo: null, subject: { ...subject, address: 'เลขที่ XX ตำบลตัวอย่าง อำเภอตัวอย่าง จังหวัดตัวอย่าง' }, caseNo: source?.caseNo || draft.legacyCaseNo || `MAN-${n}/2569`, court: draft.court || 'ศาลอาญาตัวอย่าง', bureau: source?.bureau || window.Activity9Store.currentUser().unit, owner: source?.owner || window.Activity9Store.currentUser().name, source: { type: draft.sourceMode, caseId: source?.id || `MANUAL-${n}`, version: source?.version || '1.0', snapshotAt: source?.snapshotAt || next.clock, reason: draft.manualReason || null }, issueDate: null, limitationDate: '2029-08-04', due180: null, updatedAt: next.clock, dimensions: { request: 'Draft', review: 'NotStarted', dispatch: 'NotPrepared', enforcement: 'NotStarted', handover: 'NotRequired', termination: 'NoReason', day180: 'NotDue' }, currentStage: 'ตรวจความพร้อม', currentTask: 'ตรวจความพร้อมก่อนยื่นศาล', responsible: window.Activity9Seed.roles.PaccSupervisor.name, tasks: [{ id: `TK-${id}`, recordId: id, type: 'ReviewReadiness', title: 'ตรวจความพร้อมคำขอ', assignedRole: 'PaccSupervisor', assignedUnit: window.Activity9Seed.roles.PaccSupervisor.unit, assignedUser: window.Activity9Seed.roles.PaccSupervisor.name, createdAt: next.clock, dueDate: '2026-08-07', status: 'Open', priority: 'High', actionTab: 'court', reason: 'เจ้าของสำนวนส่งตรวจความพร้อม', sourceEvent: 'SubmitReadiness' }], documents: [{ id: `DOC-${id}`, type: 'WarrantRequest', name: 'คำร้องขอออกหมายจับ', version: 1, status: 'AwaitingReview', createdAt: next.clock, createdBy: window.Activity9Store.currentUser().name, attachments: [] }, { id: `DOC-${id}-A1`, type: 'InitiationOrder', name: 'หนังสือหรือคำสั่งที่เป็นเหตุเริ่มดำเนินการ', version: 1, status: 'Ready', createdAt: next.clock, createdBy: window.Activity9Store.currentUser().name, attachments: [] }, { id: `DOC-${id}-A2`, type: 'FactSummary', name: 'สรุปข้อเท็จจริง', version: 1, status: 'Ready', createdAt: next.clock, createdBy: window.Activity9Store.currentUser().name, attachments: [] }, { id: `DOC-${id}-A3`, type: 'SubjectProfile', name: 'ข้อมูลผู้ต้องหา', version: 1, status: 'Ready', createdAt: next.clock, createdBy: window.Activity9Store.currentUser().name, attachments: [] }, { id: `DOC-${id}-A4`, type: 'EvidenceAttachment', name: 'เอกสารประกอบพยานหลักฐาน', version: 1, status: 'Ready', createdAt: next.clock, createdBy: window.Activity9Store.currentUser().name, attachments: [] }], audits: [{ id: `AU-${id}`, at: next.clock, action: 'สร้างคำขอและส่งตรวจความพร้อม', actorRole: next.currentRole, actor: window.Activity9Store.currentUser().name, detail: `ต้นทาง ${draft.sourceMode} เก็บ Source ID และ Snapshot แล้ว`, dimension: 'Request', from: 'Draft', to: 'AwaitingReadinessReview' }], corrections: [], courtAttempts: [], dispatchAttempts: [], enforcementReports: [], handoverAttempts: [], terminationAttempts: [], withdrawalAttempts: [], day180Issues: [], notifications: [], versions: [{ version: 1, at: next.clock, by: window.Activity9Store.currentUser().name, note: 'สร้างและส่งตรวจ' }], dataQuality: { name: true, citizenId: true, address: true, issueDate: true, enforcementConsistent: true, withdrawalConsistent: true } };
      record.dimensions.request = 'AwaitingReadinessReview'; record.warrantFields = warrantFieldDefaults(); next.records.unshift(record); next.createDraft = { step: 1, sourceMode: 'Activity5', sourceCaseId: next.sourceCases[1].id }; return record;
    });
    toast('ส่งตรวจความพร้อมแล้ว', `สถานะใหม่ “รอตรวจความพร้อม” และสร้างงานให้ ${window.Activity9Seed.roles.PaccSupervisor.title}`, 'success'); window.Activity9Router.go(`/warrant/${created.id}?tab=overview`);
